(function() {var stage=document.getElementById('egmainVideoStage');if(!stage) return;var videos=Array.prototype.slice.call(stage.querySelectorAll('video'));var dots=document.querySelectorAll('#egmainDots .egmain-dot');if(!videos.length) return;var current=0;function show(i) {videos.forEach(function(v,idx) {v.classList.toggle('is-active',idx===i);if(dots[idx]) dots[idx].classList.toggle('is-active',idx===i);});var v=videos[i];try {v.currentTime=0;v.play();} catch(e) {}}
function next() {var prev=current;current=(current + 1)%videos.length;show(current);setTimeout(function() {if(videos[prev]) videos[prev].pause();},1200);}
videos.forEach(function(v) {v.addEventListener('ended',next);});var first=videos[0];function start() {show(0);};if(first.readyState>=2) start();else first.addEventListener('loadeddata',start,{once:true});setTimeout(start,2000);})();

function t994_luma(color) {var isArray=Array.isArray(color);if(typeof color=='undefined') {return 'black';};if(color.indexOf('rgb')!=0&&!isArray) {return 'black';}
var rgb=isArray?color:color.split('(')[1].split(')')[0].split(',');if(rgb.length<3) {return 'black';}
return((0.2126*rgb[0]) +(0.7152*rgb[1]) +(0.0722*rgb[2]))>128?'black':'white';};if(window.innerWidth<960) {var loaderColor;var outerLoaderColor;loaderColor=t994_luma([34,34,34,1]);outerLoaderColor=loaderColor=='black'?'rgba(0, 0, 0, 0.5)':'rgba(255, 255, 255, 0.5)';var rec=document.querySelector('#rec2040537801');if(rec) {var louderOuter=rec.querySelector('.t994__loader-outer');var louderInner=rec.querySelector('.t994__loader-inner');if(louderOuter) louderOuter.style.backgroundColor=outerLoaderColor;if(louderInner) louderInner.style.backgroundColor=loaderColor;}}
